import numpy as np

M64 = np.uint64(0xFFFFFFFFFFFFFFFF)

def _rotl(x, r):
    r %= 64
    if r == 0:
        return x
    return ((x << np.uint64(r)) | (x >> np.uint64(64 - r))) & M64

def _maj5(a, b, c, d, e):
    return ((a&b)|(a&c)|(a&d)|(a&e)|(b&c)|(b&d)|(b&e)|(c&d)|(c&e)|(d&e)) & M64

STAGES = [(1, 7, 17, 33, 9, 27), (5, 15, 29, 45, 19, 39)]

def mix_np(V, K):
    x = np.asarray(V, dtype=np.uint64); k = np.asarray(K, dtype=np.uint64)
    x = (x ^ k) & M64
    # stage 0
    r0,r1,r2,r3,r4,r5 = _rotl(x,1), _rotl(x,7), _rotl(x,17), _rotl(x,33), _rotl(x,9), _rotl(x,27)
    x = (x ^ ((~r0)&r1) ^ ((~r2)&r3) ^ r4 ^ r5) & M64
    # stage 1
    r0,r1,r2,r3,r4,r5 = _rotl(x,5), _rotl(x,15), _rotl(x,29), _rotl(x,45), _rotl(x,19), _rotl(x,39)
    x = (x ^ ((~r0)&r1) ^ ((~r2)&r3) ^ r4 ^ r5) & M64
    x = (x ^ _rotl(k, 13)) & M64
    return x & M64
def mix(v, k):
    return int(mix_np(np.uint64(v), np.uint64(k)))
